import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward_cute(torch::Tensor x,
                                  torch::Tensor w,
                                  c10::optional<torch::Tensor> b,
                                  int stride,
                                  int pad_h,
                                  int pad_w,
                                  int dil_h,
                                  int dil_w);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <c10/cuda/CUDAGuard.h>
#include <cute/tensor.hpp>

using namespace cute;
// Asynchronous 4-byte global->shared copy with zero-fill for out-of-bounds
// elements (src-size = 0 zero-fills the whole 4-byte destination). Falls
// back to a synchronous guarded copy on pre-sm_80 architectures.
__device__ __forceinline__ void cp_async4(void* smem_dst, const float* gmem_src, bool valid) {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
  const unsigned dst = (unsigned)__cvta_generic_to_shared(smem_dst);
  const int src_size = valid ? 4 : 0;
  asm volatile("cp.async.ca.shared.global [%0], [%1], 4, %2;\n" ::"r"(dst), "l"(gmem_src), "r"(src_size));
#else
  *reinterpret_cast<float*>(smem_dst) = valid ? *gmem_src : 0.0f;
#endif
}
__device__ __forceinline__ void cp_async_commit() {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
  asm volatile("cp.async.commit_group;\n" ::);
#endif
}
template <int N>
__device__ __forceinline__ void cp_async_wait_group() {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
  asm volatile("cp.async.wait_group %0;\n" ::"n"(N));
#endif
}

template <int OC_TILE, int C_CHUNK, int OH_TILE, int OW_TILE, int OW_BLOCK>
__global__ void __launch_bounds__(OH_TILE * OW_TILE, 3) conv2d_direct_cute_kernel(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ B,
    float* __restrict__ Y,
    int N, int C, int H, int Win,
    int OC, int KH, int KW,
    int Hout, int Wout,
    int stride, int pad_h, int pad_w,
    int dil_h, int dil_w,
    int num_oc_tiles)
{
  constexpr int Threads = OH_TILE * OW_TILE;
  constexpr int OUT_W_TILE = OW_TILE * OW_BLOCK;
  static_assert(Threads == 256, "This kernel expects 256 threads.");
  static_assert(C_CHUNK == 4, "This kernel stages four input channels per vector.");
  extern __shared__ float smem[];
  float* sX_ptr = smem;
  const int tid = threadIdx.x;
  const int tx = tid % OW_TILE;
  const int ty = tid / OW_TILE;
  const int ow0 = blockIdx.x * OUT_W_TILE;
  const int oh0 = blockIdx.y * OH_TILE;
  const int n   = blockIdx.z / num_oc_tiles;
  const int oc0 = (blockIdx.z % num_oc_tiles) * OC_TILE;
  const int ih_tile = (OH_TILE - 1) * stride + dil_h * (KH - 1) + 1;
  const int iw_tile = (OUT_W_TILE - 1) * stride + dil_w * (KW - 1) + 1;
  const int ih_base = oh0 * stride - pad_h;
  const int iw_base = ow0 * stride - pad_w;
  const int64_t sXn = (int64_t)C * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sWo = (int64_t)C * KH * KW;
  const int64_t sWc = (int64_t)KH * KW;
  const int64_t sWh = (int64_t)KW;
  const int64_t sYn = (int64_t)OC * Hout * Wout;
  const int64_t sYo = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  auto mX = make_tensor(
      make_gmem_ptr(X),
      make_shape(N, C, H, Win),
      make_stride(sXn, sXc, sXh, Int<1>{})
  );
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(OC, C, KH, KW),
      make_stride(sWo, sWc, sWh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y),
      make_shape(N, OC, Hout, Wout),
      make_stride(sYn, sYo, sYh, Int<1>{})
  );
  auto sX = make_tensor(
      make_smem_ptr(sX_ptr),
      make_layout(
          make_shape(ih_tile, iw_tile, Int<C_CHUNK>{}),
          make_stride((int64_t)iw_tile * C_CHUNK, Int<C_CHUNK>{}, Int<1>{})
      )
  );
  // Register blocking over the output-width dimension: each thread computes
  // OW_BLOCK outputs spaced OW_TILE apart. OC_TILE is kept moderate so the
  // accumulator register footprint stays low: the previous 16-wide output-
  // channel block pushed the kernel past 100 registers/thread and capped
  // occupancy at ~33%; the rebalanced tile lets more CTAs reside per SM.
  float acc[OW_BLOCK][OC_TILE];
  #pragma unroll
  for (int j = 0; j < OW_BLOCK; ++j) {
    #pragma unroll
    for (int co = 0; co < OC_TILE; ++co) {
      acc[j][co] = 0.0f;
    }
  }
  const int oh = oh0 + ty;
  const bool row_valid = (oh < Hout);
  int ow[OW_BLOCK];
  bool out_valid[OW_BLOCK];
  #pragma unroll
  for (int j = 0; j < OW_BLOCK; ++j) {
    ow[j] = ow0 + tx + j * OW_TILE;
    out_valid[j] = row_valid && (ow[j] < Wout);
  }
  const float* __restrict__ w_oc0 = W + (int64_t)oc0 * sWo;
  const int tile_hw = ih_tile * iw_tile;
  const int x_elems = C_CHUNK * tile_hw;
  const size_t buf_elems = (size_t)x_elems;
  const int w_elems = C_CHUNK * KW * OC_TILE;
  const size_t w_buf_elems = (size_t)w_elems;
  float* sW_ptr = sX_ptr + 2 * buf_elems;
  // Stage activations and one weight row in channel-inner shared-memory
  // layouts. Each compute step can then load four channels with one
  // 16-byte shared-memory access for both convolution operands. The
  // per-kh weight tile is double-buffered, adding only a small amount of
  // shared memory while removing repeated global weight loads from the
  // inner loop.
  auto load_x_tile = [&](int c0, int buf) {
    float* sbase = sX_ptr + (size_t)buf * buf_elems;
    for (int idx = tid; idx < x_elems; idx += Threads) {
      const int cc = idx / tile_hw;
      const int rem = idx - cc * tile_hw;
      const int th = rem / iw_tile;
      const int tw = rem - th * iw_tile;
      const int c = c0 + cc;
      const int ih = ih_base + th;
      const int iw = iw_base + tw;
      const bool valid = (c < C) && (ih >= 0) && (ih < H) && (iw >= 0) && (iw < Win);
      const float* src = valid ? &mX(n, c, ih, iw) : X;
      const int dst = (th * iw_tile + tw) * C_CHUNK + cc;
      cp_async4(sbase + dst, src, valid);
    }
  };
  auto load_w_tile = [&](int c0, int kh, int buf) {
    float* wbase = sW_ptr + (size_t)buf * w_buf_elems;
    for (int idx = tid; idx < w_elems; idx += Threads) {
      const int kw = idx % KW;
      const int rem = idx / KW;
      const int cc = rem % C_CHUNK;
      const int co = rem / C_CHUNK;
      const int c = c0 + cc;
      const int oc = oc0 + co;
      const bool valid = (c < C) && (oc < OC);
      const float* src = valid ? &mW(oc, c, kh, kw) : W;
      const int dst = (kw * OC_TILE + co) * C_CHUNK + cc;
      cp_async4(wbase + dst, src, valid);
    }
  };
  load_x_tile(0, 0);
  load_w_tile(0, 0, 0);
  cp_async_commit();
  int xbuf = 0;
  int wbuf = 0;
  for (int c0 = 0; c0 < C; c0 += C_CHUNK) {
    const int next_c0 = c0 + C_CHUNK;
    for (int kh = 0; kh < KH; ++kh) {
      const bool has_next_kh = (kh + 1 < KH);
      if (has_next_kh) {
        load_w_tile(c0, kh + 1, wbuf ^ 1);
        cp_async_commit();
        cp_async_wait_group<1>();
      } else if (next_c0 < C) {
        load_x_tile(next_c0, xbuf ^ 1);
        load_w_tile(next_c0, 0, wbuf ^ 1);
        cp_async_commit();
        cp_async_wait_group<1>();
      } else {
        cp_async_wait_group<0>();
      }
      __syncthreads();
      const float* __restrict__ sx_base = sX_ptr + (size_t)xbuf * buf_elems;
      const float* __restrict__ sw_base = sW_ptr + (size_t)wbuf * w_buf_elems;
      if (row_valid) {
        const int th = ty * stride + kh * dil_h;
        for (int kw = 0; kw < KW; ++kw) {
          const int tw0 = tx * stride + kw * dil_w;
          float4 xv[OW_BLOCK];
          #pragma unroll
          for (int j = 0; j < OW_BLOCK; ++j) {
            const int tw = tw0 + j * OW_TILE * stride;
            const int xoff = (th * iw_tile + tw) * C_CHUNK;
            xv[j] = *reinterpret_cast<const float4*>(sx_base + xoff);
          }
          #pragma unroll
          for (int co = 0; co < OC_TILE; ++co) {
            const int woff = (kw * OC_TILE + co) * C_CHUNK;
            const float4 wv = *reinterpret_cast<const float4*>(sw_base + woff);
            #pragma unroll
            for (int j = 0; j < OW_BLOCK; ++j) {
              acc[j][co] += xv[j].x * wv.x;
              acc[j][co] += xv[j].y * wv.y;
              acc[j][co] += xv[j].z * wv.z;
              acc[j][co] += xv[j].w * wv.w;
            }
          }
        }
      }
      __syncthreads();
      wbuf ^= 1;
      if (!has_next_kh && next_c0 < C) {
        xbuf ^= 1;
      }
    }
  }
  if (row_valid) {
    #pragma unroll
    for (int j = 0; j < OW_BLOCK; ++j) {
      if (out_valid[j]) {
        #pragma unroll
        for (int co = 0; co < OC_TILE; ++co) {
          const int oc = oc0 + co;
          if (oc < OC) {
            const float bias = (B != nullptr) ? B[oc] : 0.0f;
            mY(n, oc, oh, ow[j]) = acc[j][co] + bias;
          }
        }
      }
    }
  }
}

torch::Tensor conv2d_forward_cute(torch::Tensor x,
                                  torch::Tensor w,
                                  c10::optional<torch::Tensor> b,
                                  int stride,
                                  int pad_h,
                                  int pad_w,
                                  int dil_h,
                                  int dil_w)
{
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors.");
  TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
              "x and w must be float32.");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W].");
  TORCH_CHECK(w.dim() == 4, "w must be [OC, C, KH, KW].");
  TORCH_CHECK(stride > 0 && dil_h > 0 && dil_w > 0, "stride/dilation must be positive.");
  TORCH_CHECK(pad_h >= 0 && pad_w >= 0, "padding must be non-negative.");

  const at::cuda::CUDAGuard device_guard(x.device());

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  const int64_t N = x_c.size(0);
  const int64_t C = x_c.size(1);
  const int64_t H = x_c.size(2);
  const int64_t Win = x_c.size(3);

  const int64_t OC = w_c.size(0);
  const int64_t WC = w_c.size(1);
  const int64_t KH = w_c.size(2);
  const int64_t KW = w_c.size(3);
  TORCH_CHECK(WC == C, "w.size(1) must equal x.size(1).");

  const int64_t Hout = (H + 2LL * pad_h - (int64_t)dil_h * (KH - 1) - 1) / stride + 1;
  const int64_t Wout = (Win + 2LL * pad_w - (int64_t)dil_w * (KW - 1) - 1) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid convolution output size.");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.is_cuda() && b_c.scalar_type() == at::kFloat,
                "bias must be CUDA float32.");
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC].");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, Hout, Wout}, x_c.options());

  constexpr int OC_TILE = 8;
  constexpr int C_CHUNK = 4;
  constexpr int OH_TILE = 16;
  constexpr int OW_TILE = 16;
  constexpr int OW_BLOCK = 2;
  constexpr int Threads = OH_TILE * OW_TILE;

  const int ih_tile = (OH_TILE - 1) * stride + dil_h * (int)(KH - 1) + 1;
  const int iw_tile = (OW_TILE * OW_BLOCK - 1) * stride + dil_w * (int)(KW - 1) + 1;

  const size_t x_smem_bytes =
      2ULL * (size_t)C_CHUNK * ih_tile * iw_tile * sizeof(float);
  const size_t w_smem_bytes =
      2ULL * (size_t)C_CHUNK * (size_t)KW * (size_t)OC_TILE * sizeof(float);
  const size_t smem_bytes = x_smem_bytes + w_smem_bytes;

  const int num_oc_tiles = (int)((OC + OC_TILE - 1) / OC_TILE);
  dim3 block(Threads);
  dim3 grid(
      (unsigned)((Wout + OW_TILE * OW_BLOCK - 1) / (OW_TILE * OW_BLOCK)),
      (unsigned)((Hout + OH_TILE - 1) / OH_TILE),
      (unsigned)(N * num_oc_tiles)
  );

  auto kernel = conv2d_direct_cute_kernel<OC_TILE, C_CHUNK, OH_TILE, OW_TILE, OW_BLOCK>;
  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(kernel, cudaFuncAttributeMaxDynamicSharedMemorySize,
                         (int)smem_bytes);
  }

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  kernel<<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)C, (int)H, (int)Win,
      (int)OC, (int)KH, (int)KW,
      (int)Hout, (int)Wout,
      stride, pad_h, pad_w, dil_h, dil_w,
      num_oc_tiles
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_direct_cute_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_direct_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_forward_cute"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Standard 2D convolution implemented with one cooperative tiled CuTe/CUDA kernel.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: tuple,
                 stride: int = 1,
                 padding: tuple = (0, 0),
                 dilation: tuple = (1, 1),
                 bias: bool = False):
        super().__init__()
        assert isinstance(kernel_size, tuple) and len(kernel_size) == 2
        assert isinstance(padding, tuple) and len(padding) == 2
        assert isinstance(dilation, tuple) and len(dilation) == 2

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = (int(kernel_size[0]), int(kernel_size[1]))
        self.stride = int(stride)
        self.padding = (int(padding[0]), int(padding[1]))
        self.dilation = (int(dilation[0]), int(dilation[1]))

        self.weight = nn.Parameter(
            torch.empty(self.out_channels,
                        self.in_channels,
                        self.kernel_size[0],
                        self.kernel_size[1])
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size[0] * self.kernel_size[1]
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_forward_cute(
            x,
            self.weight,
            self.bias if self.bias is not None else None,
            self.stride,
            self.padding[0],
            self.padding[1],
            self.dilation[0],
            self.dilation[1],
        )

